  push!(__eqs, RollRate ~ w_body[1])
  push!(__eqs, PitchRate ~ w_body[2])
  push!(__eqs, YawRate ~ w_body[3])
  push!(__eqs, Yaw ~ getindex(getproperty(body, :phi), 1))
  push!(__eqs, pos_x ~ getindex(getproperty(frame_a, :r_0), 1))
  push!(__eqs, pos_y ~ getindex(getproperty(frame_a, :r_0), 2))
  push!(__eqs, pos_z ~ getindex(getproperty(frame_a, :r_0), 3))
  push!(__eqs, connect(frame_a, body.frame_a, buoy_force.frame_b, buoy_torque.frame_b))

  # Return completely constructed System
  return System(__eqs, t, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
export ShipBody
